using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
namespace Ifss.Native {
    public static class NativeTimingTests {
        static int passed;static readonly List<string> Failures=new List<string>();
        static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        static void Case(string name,Action action){try{action();passed++;}catch(Exception error){Failures.Add(name+": "+error.GetBaseException().Message);}}
        static void Reject(Action action){try{action();}catch(InvalidDataException){return;}throw new InvalidOperationException("Invalid input was accepted.");}
        static long I(Dictionary<string,object> row,string key){return Convert.ToInt64(row[key]);}
        static double F(Dictionary<string,object> row,string key){return Convert.ToDouble(row[key]);}
        static List<TimingEvent> Chain(){return new List<TimingEvent>{new TimingEvent(0,0,"read_request",4096,8,123),new TimingEvent(10,1,"read_cp_begin"),new TimingEvent(20,1,"read_cp_end"),new TimingEvent(21,0,"read_wait_begin",0,1,99),new TimingEvent(50,0,"read_wait_end",0,1,99),new TimingEvent(52,0,"read_completion_request"),new TimingEvent(62,1,"read_cp_begin",1),new TimingEvent(72,1,"read_cp_end",1),new TimingEvent(80,0,"read_return",1)};}
        static List<TimingEvent> Producers(){var events=Chain();events.AddRange(new[]{new TimingEvent(11,1,"read_producer_window",4096,64,4096,8),new TimingEvent(11,1,"read_producer_coverage",1,5,0,4),new TimingEvent(12,1,"read_producer",5,99,0xabc,(3<<8)|(3<<16)),new TimingEvent(12,1,"read_producer_range",5,4096,8,7),new TimingEvent(12,1,"read_producer_time",5,1,2,99),new TimingEvent(12,1,"read_producer_domain",5,111,6,5)});return events;}
        const string Descriptor="Perf R4 descriptors: calls 10 hit 2 unknown 1 uncacheable 0 layout 3 shape 1 payload 3 layout-only 2; changed segments 4/12 infos 6 one/few/many 2/1/0; fields buffer 1 offset 4 range 2 sampler 0 view 0 image-layout 0 texel-view 0";
        const string Evidence="Perf R4 descriptors: calls 1 hit 0 unknown 1 uncacheable 0 layout 0 shape 0 payload 0 layout-only 0; changed segments 0/0 infos 0 one/few/many 0/0/0; fields buffer 0 offset 0 range 0 sampler 0 view 0 image-layout 0 texel-view 0\nPerf R4 prepare: calls 1 ms 1.000; buffers 1 ms 0.500; textures 1 ms 0.250; regular sets 0 writes 0\n";
        static List<TimingEvent> Trace(){var events=new List<TimingEvent>{new TimingEvent(1000,0,"frame_sample",0,1000,0,0){Id=1},new TimingEvent(1100,0,"frame_sample",1,1100,100,100){Id=2},new TimingEvent(1200,0,"frame_sample",2,1200,100,200){Id=3}};foreach(var e in Chain()){e.Ns+=1010;e.Id=10;events.Add(e);}string[] names={"flip_request","flip_prepare","flip_ready","flip_consume","flip_present_return","flip_done"};for(int i=0;i<names.Length;++i)events.Add(new TimingEvent(1110+i*10,0,names[i]){Id=20});return events;}
        static void WriteTrace(NativeTestFixture fixture,List<TimingEvent> events,bool v3=false){
            fixture.Json("launch.json",DiagnosticData.Map("timing_profile",v3?null:"critical","optimization_v3",v3?"all":"none","diagnostic",v3?"full":null,"runtime_sha256","fixture","game_sha256","fixture"));
            fixture.Write("frames.csv","frame,elapsed_ns,interval_ns,utc_ns\n0,0,0,1767225600000000000\n1,100,100,1767225600000000100\n2,200,100,1767225600000000200\n");
            var text=new StringBuilder("thread,seq,ns,guest_frame,event,id,a,b,c,d\n");var sequences=new Dictionary<long,long>();foreach(var e in events.OrderBy(e=>e.Ns).ThenBy(e=>e.Thread)){long sequence;sequences.TryGetValue(e.Thread,out sequence);sequences[e.Thread]=sequence+1;text.Append(e.Thread+","+sequence+","+e.Ns+",0,"+e.Kind+","+e.Id+","+e.A+","+e.B+","+e.C+","+e.D+"\n");}
            fixture.Write("path-trace.csv",text.ToString());fixture.Json("path-trace.json",DiagnosticData.Map("schema",1,"clock","steady_clock_ns","complete",true,"io_failed",false,"dropped",0,"cutoff_publishers",0,"registered_threads",2,"gpu_profile_at_start",v3?2:0,"compute_hash_at_start",0,"events",events.Count));
        }
        public static void Run(string root){passed=0;Failures.Clear();
            Case("read partitions",delegate{var row=TimingAnalysis.ReadPath(Chain().AsEnumerable().Reverse());Check(I(row,"total_ns")==80&&I(row,"cpu_wait_ns")==29&&I(row,"completion_queue_ns")==10&&I(row,"handoff_and_unattributed_ns")==11,"Read stage partition changed.");Check(row.Where(pair=>pair.Key.EndsWith("_ns")&&pair.Key!="total_ns").Sum(pair=>Convert.ToInt64(pair.Value))==80,"Primary stages double counted.");});
            Case("nested fallback",delegate{var events=Chain();events.Add(new TimingEvent(64,1,"read_fallback_begin"));events.Add(new TimingEvent(70,1,"read_fallback_end"));var row=TimingAnalysis.ReadPath(events);Check(I(row,"nested_fallback")==6&&I(row,"completion_cp_ns")==10&&I(row,"total_ns")==80,"Nested fallback counted twice.");});
            Case("semaphore identity",delegate{var events=Chain();events[4].C=100;Reject(()=>TimingAnalysis.ReadPath(events));});
            Case("completion request",delegate{Reject(()=>TimingAnalysis.ReadPath(Chain().Where(e=>e.Kind!="read_completion_request")));});
            Case("return before completion",delegate{var events=Chain();events[events.Count-1].Ns=70;Reject(()=>TimingAnalysis.ReadPath(events));});
            Case("read mode and duplicate initial",delegate{var events=Chain();events[events.Count-1].A=2;Reject(()=>TimingAnalysis.ReadPath(events));events=Chain();events.Add(new TimingEvent(5,1,"read_cp_begin"));Reject(()=>TimingAnalysis.ReadPath(events));});
            Case("flip queue versus call",delegate{string[] names={"flip_request","flip_prepare","flip_ready","flip_consume","flip_present_return","flip_done"};long[] ns={0,10,40,100,130,150};var row=TimingAnalysis.FlipPath(names.Select((name,i)=>new TimingEvent(ns[i],0,name)));Check(I(row,"ready_queue_ns")==60&&I(row,"present_call_cpu_ns")==30&&I(row,"total_ns")==150,"Flip queues collapsed.");});
            Case("host identity",delegate{var begin=new TimingEvent(10,2,"host_phase_begin",2);var end=new TimingEvent(35,2,"host_phase_end",2);var row=TimingAnalysis.HostPhase(new[]{end,begin});Check(row.Item1=="present_mutex"&&row.Item2==25,"Host phase changed.");Reject(()=>TimingAnalysis.HostPhase(new[]{begin,new TimingEvent(35,3,"host_phase_end",2)}));Reject(()=>TimingAnalysis.HostPhase(new[]{begin,new TimingEvent(35,2,"host_phase_end",3)}));Reject(()=>TimingAnalysis.HostPhase(new[]{begin,new TimingEvent(5,2,"host_phase_end",2)}));Reject(()=>TimingAnalysis.HostPhase(new[]{begin}));});
            Case("producer identity",delegate{var events=Producers();var candidate=Json.Object(((List<object>)TimingAnalysis.ProducerPath(events)["candidates"])[0]);Check(I(candidate,"command")==99&&I(candidate,"scopes")==3,"Producer identity lost.");Reject(()=>TimingAnalysis.ProducerPath(events.Where(e=>e.Kind!="read_producer_domain").ToList()));events[events.Count-2].D=100;Reject(()=>TimingAnalysis.ProducerPath(events));});
            Case("producer CP lifetime",delegate{var events=Producers();events.Last().Thread=3;Reject(()=>TimingAnalysis.ProducerPath(events));events=Producers();events.Last().Ns=22;Reject(()=>TimingAnalysis.ProducerPath(events));});
            Case("producer blind spot",delegate{var events=Producers().Where(e=>!new[]{"read_producer","read_producer_range","read_producer_time","read_producer_domain"}.Contains(e.Kind)).ToList();var coverage=events.Single(e=>e.Kind=="read_producer_coverage");coverage.C=999;coverage.D=5;var row=TimingAnalysis.ProducerPath(events);Check((bool)row["blind_spot"]&&((List<object>)row["candidates"]).Count==0,"History eviction was treated as proof.");});
            Case("producer overlap and uniqueness",delegate{var events=Producers();events.Single(e=>e.Kind=="read_producer_range").B=8192;Reject(()=>TimingAnalysis.ProducerPath(events));events=Producers();events.AddRange(events.Where(e=>new[]{"read_producer","read_producer_range","read_producer_time","read_producer_domain"}.Contains(e.Kind)).Select(e=>new TimingEvent(e.Ns,e.Thread,e.Kind,4,e.B,e.C,e.D)).ToArray());Reject(()=>TimingAnalysis.ProducerPath(events));Check(!TimingAnalysis.ValidRange(UInt64.MaxValue,1),"Overflowing range accepted.");});
            Case("submission domains and feedback",delegate{var groups=new Dictionary<ulong,List<TimingEvent>>{{1,new List<TimingEvent>{new TimingEvent(20,1,"submit_queued",111,7,0,1)}},{2,new List<TimingEvent>{new TimingEvent(25,2,"submit_driver_begin",111,7,1),new TimingEvent(30,2,"submit_driver_end",111,7,1,1)}},{3,new List<TimingEvent>{new TimingEvent(40,3,"submit_driver_end",222,7,1,1)}}};Dictionary<string,long> partial;Check(TimingAnalysis.Submissions(groups,out partial).Count==2&&partial["driver_pair"]==1,"Submission domains collapsed.");groups[9]=Producers();var report=TimingAnalysis.Feedback(groups,new List<Dictionary<string,object>>{DiagnosticData.Map("request_id",9,"mode",1,"total_ns",80,"cpu_wait_ns",29)});var counts=Json.Object(report["counts"]);Check(I(counts,"linked_enqueue")==1&&I(counts,"beyond_submitted_snapshot")==1,"Feedback link changed.");Check(F(Json.Object(Json.Object(report["cpu_intervals_not_additive"])["driver_call_cpu_ns"]),"mean_ms")==5/1e6,"Driver CPU interval changed.");groups[2].Last().D=0;Reject(()=>TimingAnalysis.Submissions(groups,out partial));});
            Case("empty timeline submission",delegate{var groups=new Dictionary<ulong,List<TimingEvent>>{{1,new List<TimingEvent>{new TimingEvent(20,1,"submit_driver_begin",111,7,0),new TimingEvent(25,1,"submit_driver_end",111,7,0,1)}}};Dictionary<string,long> partial;Check(TimingAnalysis.Submissions(groups,out partial).Count==1,"Empty submission rejected.");});
            Case("submission request owner",delegate{var groups=new Dictionary<ulong,List<TimingEvent>>{{1,new List<TimingEvent>{new TimingEvent(20,1,"submit_driver_begin",111,7,1)}},{2,new List<TimingEvent>{new TimingEvent(25,1,"submit_driver_end",111,7,1,1)}}};Dictionary<string,long> partial;Reject(()=>TimingAnalysis.Submissions(groups,out partial));});
            Case("descriptor residuals",delegate{var row=TimingAnalysis.DescriptorLine(Descriptor);Check(I(row,"changed_segments")==4&&TimingAnalysis.DescriptorInvariants(row).Values.All(value=>Convert.ToInt64(value)==0),"Descriptor invariants changed.");Check(I(TimingAnalysis.DescriptorInvariants(TimingAnalysis.DescriptorLine(Descriptor.Replace("calls 10","calls 11"))),"calls_minus_reasons")==1,"Counter skew hidden.");Reject(()=>TimingAnalysis.DescriptorLine(Descriptor.Replace("calls 10","calls broken")));});
            Case("update residuals",delegate{string text="Perf A1 descriptors: calls 5 full 1 partial 3 skipped 1; write segments input 20 emitted 8 omitted 12 partial-omitted 8";var row=TimingAnalysis.UpdateLine(text);Check(I(row,"partial")==3&&TimingAnalysis.UpdateInvariants(row).Values.All(value=>Convert.ToInt64(value)==0),"Update invariants changed.");Reject(()=>TimingAnalysis.UpdateLine(text.Replace("emitted 8","emitted broken")));});
            Case("update report scope",delegate{using(var reader=new StringReader(Evidence))Check(TimingAnalysis.DescriptorSummary(reader)["updates"]==null,"Unrequested update report invented.");using(var reader=new StringReader(Evidence))Reject(()=>TimingAnalysis.DescriptorSummary(reader,true));string updates="Perf A1 descriptors: calls 3 full 1 partial 1 skipped 0; write segments input 8 emitted 5 omitted 3 partial-omitted 3\nPerf A1 descriptors: calls 1 full 0 partial 1 skipped 1; write segments input 8 emitted 1 omitted 7 partial-omitted 3\n";using(var reader=new StringReader(Evidence+updates)){var row=Json.Object(TimingAnalysis.DescriptorSummary(reader,true)["updates"]);Check((bool)row["aggregate_invariants_met"]&&((List<object>)row["snapshot_skew_intervals"]).Count==2,"Atomic snapshot skew semantics changed.");}});
            Case("SPIR-V evidence",delegate{uint[] words={0x07230203,0x00010500,0,100,0,(2<<16)|17,63,(6<<16)|353,3,20,7,0,8,(6<<16)|356,3,21,7,0,8,(4<<16)|333,2,22,7,(7<<16)|236,3,23,9,7,7,8,(7<<16)|238,3,24,9,7,7,8,(4<<16)|224,7,7,7};var bytes=new byte[words.Length*4];Buffer.BlockCopy(words,0,bytes,0,bytes.Length);var row=TimingAnalysis.DepthSpirvFacts(bytes);Check((bool)row["candidate_pattern_observed"]&&I(Json.Object(row["operations"]),"control_barrier")==1&&!row.ContainsKey("fps"),"Binary facts inferred performance.");Array.Clear(bytes,20,4);Reject(()=>TimingAnalysis.DepthSpirvFacts(bytes));Reject(()=>TimingAnalysis.DepthSpirvFacts(new byte[3]));});
            Case("frame boundary",delegate{using(var reader=new StringReader("frame,elapsed_ns,interval_ns\n0,0,0\n1,11000000000,11000000000\n2,11500000000,500000000\n3,11900000000,400000000\n")){var row=TimingAnalysis.FrameSummary(reader,10,2);Check(row.Rows.Keys.OrderBy(value=>value).SequenceEqual(new[]{2UL,3UL})&&I(row.Report,"intervals_crossing_start_excluded")==1&&Math.Abs(F(row.Report,"elapsed_s")-.9)<1e-10,"Partial frame inflated selected window.");}});
            Case("nearest rank percentiles",delegate{var row=TimingAnalysis.Stats(Enumerable.Range(1,100).Select(value=>value*1000000L));Check(F(row,"p95_ms")==95&&F(row,"p99_ms")==99&&F(row,"mean_ms")==50.5,"Percentiles changed.");});
            using(var fixture=new NativeTestFixture(root,"timing")){
                Case("two-pass complete report",delegate{WriteTrace(fixture,Trace());var report=TimingAnalysis.Analyze(fixture.Root,0,.000000201);Check((bool)report["format_usable"]&&!(bool)report["performance_acceptance"]&&I(Json.Object(report["readback"]),"complete_chains")==1,"Complete synthetic trace failed: "+Json.Encode(report["errors"]));});
                Case("interior frame gap",delegate{WriteTrace(fixture,Trace().Where(e=>e.Kind!="frame_sample"||e.A!=1).ToList());var report=TimingAnalysis.Analyze(fixture.Root,0,.000000201);Check(!(bool)report["format_usable"]&&I(Json.Object(report["frame_join"]),"missing_interior")==1,"Interior join gap accepted.");});
                Case("trace loss metadata",delegate{WriteTrace(fixture,Trace());var meta=Json.Read(fixture.Paths.Child("path-trace.json"));meta["dropped"]=1;fixture.Json("path-trace.json",meta);Check(!(bool)TimingAnalysis.Analyze(fixture.Root,0,.000000201)["format_usable"],"Loss metadata accepted.");});
                Case("nullable V3 profile",delegate{WriteTrace(fixture,Trace(),true);var report=TimingAnalysis.Analyze(fixture.Root,0,.000000201);Check((string)report["profile"]=="v3-full"&&report.ContainsKey("host_phase_coverage"),"V3 null timing profile was not adapted.");});
                Case("nonfinite window rejection",delegate{Reject(()=>TimingAnalysis.ResolveWindow(fixture.Root,Double.NaN,null));Reject(()=>TimingAnalysis.ResolveWindow(fixture.Root,0,Double.PositiveInfinity));});
            }
            if(Failures.Count>0)throw new InvalidOperationException(String.Join("\n",Failures));Console.WriteLine("Native timing regressions passed: "+passed+" cases, including complete/invalid two-pass reports. No game or profiler was run.");
        }
    }
}
